const STY = (bg, w, h, x, y) => `position:absolute;width:${w}px;height:${h}px;left:${x}px;top:${y}px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border-radius:46px;box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.5);background:${bg};color:#ffffff;font-family:inherit;font-weight:800;line-height:1.1;font-size:42px;opacity:0;transform:scale(0.8);`;
const B1 = `linear-gradient(180deg,color-mix(in srgb,var(--acc) 72%,#fff),var(--acc) 55%,color-mix(in srgb,var(--acc) 84%,#000))`;
const B2 = `linear-gradient(180deg,color-mix(in srgb,var(--acc2) 72%,#fff),var(--acc2) 55%,color-mix(in srgb,var(--acc2) 84%,#000))`;

root.innerHTML = `
  <svg style="position:absolute;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:8;stroke-linecap:round;opacity:0.4">
    <path id="l0" d="M470 450 L470 250" />
    <path id="l1" d="M350 580 L230 790" />
    <path id="l2" d="M590 580 L710 790" />
  </svg>
  <div id="c0" style="${STY(B1, 500, 180, 220, 440)}font-size:48px;">RIEMANN<br>HYPOTHESIS</div>
  <div id="c1" style="${STY(B2, 440, 140, 250, 110)}">MIT EXPERTS<br>BUZZING</div>
  <div id="c2" style="${STY(B2, 420, 140, 30, 790)}font-size:36px;">CODE<br>COMPILED</div>
  <div id="c3" style="${STY(B2, 420, 140, 490, 790)}font-size:36px;">FORMALIZED<br>MATH HOLDS</div>
`;

const cards = [0, 1, 2, 3].map(i => root.querySelector('#c' + i));
const lines = [0, 1, 2].map(i => {
  const el = root.querySelector('#l' + i);
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});

function frame(t, p, d) {
  // 1. Central Hub Pops
  const s0 = spr(t, 0, 0.8, 12);
  cards[0].style.opacity = clamp(t * 4);
  cards[0].style.transform = `scale(${0.8 + s0 * 0.2})`;

  // 2. Lines extend
  lines.forEach((line, i) => {
    const start = 0.8 + i * 0.4;
    const lp = clamp((t - start) * 2);
    line.el.style.strokeDashoffset = line.len * (1 - E_OUT(lp));
  });

  // 3. Peripheral Nodes Pop
  cards.slice(1).forEach((card, i) => {
    const start = 1.4 + i * 0.4;
    const s = spr(t, start, 0.8, 10);
    card.style.opacity = clamp((t - start) * 5);
    card.style.transform = `scale(${0.7 + s * 0.3})`;
  });

  // Subtle drift to keep it alive before p=.55
  const drift = E_OUT(clamp(p / 0.55)) * 20;
  root.style.transform = `translateY(${20 - drift}px)`;
}
